function act(obs, mem) {
  function n180(a) {
    a = a % 360;
    if (a > 180) a -= 360;
    if (a < -180) a += 360;
    return a;
  }
  function cl(v, lo, hi) { return v < lo ? lo : (v > hi ? hi : v); }
  function fin(l, r) {
    l = cl(l, -1, 1);
    r = cl(r, -1, 1);
    if (l > 0 && l < 0.15) l = 0.15;
    else if (l < 0 && l > -0.15) l = -0.15;
    if (r > 0 && r < 0.15) r = 0.15;
    else if (r < 0 && r > -0.15) r = -0.15;
    return { left: l, right: r };
  }

  if (!mem.init) {
    mem.init = 1;
    mem.prevH = 0;
    mem.hR = 0;
    mem.wS = 0;
    mem.bias = 0;
    mem.rs = [10, 10, 10, 10, 10];
    mem.dS = 10;
    mem.vh = [];
    mem.hist = [];
    mem.mode = 0;
    mem.modeT = 0;
    mem.recT = -99;
    mem.recDir = 1;
  }

  var t = Number(obs.t) || 0;
  var px = Number(obs.x) || 0;
  var py = Number(obs.y) || 0;
  var hd = Number(obs.heading) || 0;
  var tx = Number(obs.targetX) || 0;
  var ty = Number(obs.targetY) || 0;
  var spd = Number(obs.speed) || 0;

  // --- heading rate (for damping) ---
  var hr = n180(hd - mem.prevH) / 0.05;
  mem.prevH = hd;
  mem.hR = 0.75 * mem.hR + 0.25 * hr;

  // --- rays: asymmetric temporal filter (instant attack, slow release) ---
  var cur = [];
  for (var i = 0; i < 5; i++) {
    var v = Number(obs.rays ? obs.rays[i] : 10);
    if (!isFinite(v)) v = 10;
    cur.push(cl(v, 0.05, 10));
  }
  for (i = 0; i < 5; i++) {
    var s = 0.5 * mem.rs[i] + 0.5 * cur[i];
    mem.rs[i] = Math.min(cur[i], s);
  }
  var rr = mem.rs;

  // --- compass bias from GPS velocity, only while running straight ---
  mem.vh.push([t, px, py, hd]);
  if (mem.vh.length > 11) mem.vh.shift();
  if (mem.vh.length === 11) {
    var a0 = mem.vh[0], a1 = mem.vh[10];
    var span = a1[0] - a0[0];
    var ddx = a1[1] - a0[1], ddy = a1[2] - a0[2];
    var dist = Math.sqrt(ddx * ddx + ddy * ddy);
    var dh = Math.abs(n180(a1[3] - a0[3]));
    if (span > 0.35 && dist > 1.0 && dh < 10) {
      var b = n180(Math.atan2(ddy, ddx) * 180 / Math.PI - a1[3]);
      if (Math.abs(b) < 40) {
        mem.bias = cl(mem.bias * 0.97 + b * 0.03, -25, 25);
      }
    }
  }

  // --- target geometry ---
  var dx = tx - px, dy = ty - py;
  var td = Math.sqrt(dx * dx + dy * dy);
  var tdist = td > 0.02 ? td : 0.02;
  var err = n180(Math.atan2(dy, dx) * 180 / Math.PI - mem.bias - hd);

  // --- progress / stuck detection ---
  mem.hist.push([t, px, py]);
  if (mem.hist.length > 13) mem.hist.shift();
  var disp = 99;
  if (mem.hist.length >= 11) {
    var h = mem.hist[0];
    if (t - h[0] > 0.4) {
      var ux = px - h[1], uy = py - h[2];
      disp = Math.sqrt(ux * ux + uy * uy);
    }
  }

  if (mem.mode === 0) {
    if (disp < 0.1 && spd < 0.35 && t > 2.0 && (t - mem.recT) > 1.5 && tdist > 1.0) {
      mem.mode = 1;
      mem.modeT = 0;
      mem.recT = t;
      mem.recDir = (rr[4] >= rr[0]) ? 1 : -1;
    }
  }

  // --- escape manoeuvre: back away, then swing toward open side ---
  if (mem.mode === 1) {
    mem.modeT += 0.05;
    if (mem.modeT < 0.85) {
      return fin(mem.recDir > 0 ? -0.95 : -0.4, mem.recDir > 0 ? -0.4 : -0.95);
    }
    if (mem.modeT < 1.7) {
      return fin(mem.recDir > 0 ? 0.4 : 1, mem.recDir > 0 ? 1 : 0.4);
    }
    mem.mode = 0;
    mem.hist.length = 0;
    mem.hR = 0;
    mem.wS = 0;
    mem.dS = 10;
  }

  // --- clearance profile in robot frame (interpolated from 5 rays) ---
  function clrAt(a) {
    if (a <= -60) return rr[0];
    if (a >= 60) return rr[4];
    if (a < -30) return rr[0] + (rr[1] - rr[0]) * (a + 60) / 30;
    if (a < 0) return rr[1] + (rr[2] - rr[1]) * (a + 30) / 30;
    if (a < 30) return rr[2] + (rr[3] - rr[2]) * a / 30;
    return rr[3] + (rr[4] - rr[3]) * (a - 30) / 30;
  }

  // --- pick best heading: open space minus misalignment with target ---
  var lam = tdist < 2.5 ? 0.10 : (tdist < 6 ? 0.06 : 0.04);
  var pen = tdist < 2.2 ? 0.6 : 1.5;
  var bestA = cl(err, -60, 60), bestS = -1e9;
  for (var a = -60; a <= 60; a += 5) {
    var c = clrAt(a);
    var ad = Math.abs(n180(a - err));
    var sc = Math.min(c, 8) - lam * ad - Math.max(0, 3 - c) * pen;
    if (sc > bestS) { bestS = sc; bestA = a; }
  }

  // --- steering with rate damping and smoothing ---
  var w = cl(bestA / 30, -1, 1);
  w -= cl(0.0022 * mem.hR, -0.35, 0.35);
  w = cl(w, -1, 1);
  mem.wS = 0.6 * mem.wS + 0.4 * w;

  // --- speed: gated by nearest clearance (noise robust) ---
  var dSpeed = Math.min(rr[2], (rr[1] + rr[3]) / 2, (rr[0] + rr[4]) / 2);
  mem.dS = (dSpeed < mem.dS) ? (0.55 * mem.dS + 0.45 * dSpeed) : (0.9 * mem.dS + 0.1 * dSpeed);

  var v = 1;
  v *= cl(mem.dS / 3.5, 0.28, 1);
  v *= 1 - 0.5 * Math.abs(bestA) / 60;
  v *= 1 - 0.3 * Math.abs(err) / 120;
  if (tdist < 4) v *= cl(0.5 + 0.125 * tdist, 0.5, 1);
  v = cl(v, 0.12, 1);

  return fin(v - mem.wS, v + mem.wS);
}

function act(obs, mem) {
  function n180(a) {
    return ((a % 360) + 540) % 360 - 180;
  }
  function cl(v, lo, hi) { return v < lo ? lo : (v > hi ? hi : v); }

  if (!mem.init) {
    mem.init = 1;
    mem.ph = 0;
    mem.pr = 0;
    mem.rays = [10, 10, 10, 10, 10];
    mem.mode = 0;
    mem.mt = 0;
    mem.posh = [];
    mem.hrate = 0;
  }

  var t = +obs.t || 0;
  var px = +obs.x || 0;
  var py = +obs.y || 0;
  var hd = +obs.heading || 0;
  var tx = +obs.targetX || 0;
  var ty = +obs.targetY || 0;

  // Smooth rays (fast attack, slow release for safety)
  for (var i = 0; i < 5; i++) {
    var v = +obs.rays[i];
    if (!isFinite(v) || v <= 0) v = 10;
    v = cl(v, 0.05, 10);
    mem.rays[i] = Math.min(v, 0.6 * mem.rays[i] + 0.4 * v);
  }
  var rr = mem.rays.slice();

  // Heading rate (EMA)
  var dhd = n180(hd - mem.ph);
  mem.ph = hd;
  mem.hrate = 0.85 * mem.hrate + 0.15 * (dhd / 0.05);

  // Target direction from GPS
  var dx = tx - px, dy = ty - py;
  var dist = Math.sqrt(dx * dx + dy * dy) || 0.01;
  var desiredH = Math.atan2(dy, dx) * 180 / Math.PI;
  var hErr = n180(desiredH - hd);
  if (Math.abs(hErr) < 2) hErr = 0;

  // Obstacle avoidance from rays
  var angles = [-60, -30, 0, 30, 60];
  var avoid = 0;
  for (i = 0; i < 5; i++) {
    var r = rr[i];
    if (r < 5) {
      var s = cl((5 - r) / 5, 0, 1);
      s = s * s;
      avoid -= s * angles[i] / 60;
    }
  }
  // Center obstacle: push toward more open side
  if (rr[2] < 3) {
    var push = (3 - rr[2]) / 3;
    avoid += (rr[3] + rr[4] > rr[0] + rr[1] ? push : -push) * 1.5;
  }
  avoid = cl(avoid, -1, 1);

  // Steering: PD + avoidance with rate limiting
  var steer = 0.010 * hErr - 0.002 * mem.hrate + 0.6 * avoid;
  steer = cl(steer, mem.pr - 0.04, mem.pr + 0.04);
  steer = cl(steer, -0.45, 0.45);
  mem.pr = steer;

  // Speed control
  var minRay = Math.min(rr[0], rr[1], rr[2], rr[3], rr[4]);
  var v = 1.0;
  if (minRay < 5) v = cl(0.12 + 0.176 * minRay, 0.12, 1);
  v *= 1 - 0.3 * Math.abs(steer) / 0.45;
  v *= 1 - 0.3 * Math.min(1, Math.abs(hErr) / 90);
  if (dist < 3) v = Math.min(v, 0.2 + 0.267 * dist);
  v = Math.min(v, 1 - Math.abs(steer));
  v = cl(v, 0.08, 1);

  // Stuck detection
  mem.posh.push([t, px, py]);
  if (mem.posh.length > 14) mem.posh.shift();

  if (mem.mode === 0 && mem.posh.length >= 10) {
    var o = mem.posh[0];
    if (t - o[0] > 0.45) {
      var dd = Math.sqrt((px - o[1]) * (px - o[1]) + (py - o[2]) * (py - o[2]));
      if (dd < 0.25 && dist > 1.5 && t > 1) {
        mem.mode = 1;
        mem.mt = 0;
        mem.posh.length = 0;
        mem.pr = 0;
      }
    }
  }

  // Escape manoeuvre: reverse-turn toward open side, then forward-turn
  if (mem.mode === 1) {
    mem.mt += 0.05;
    var dir = rr[4] >= rr[0] ? 1 : -1;
    if (mem.mt < 1.5) return { left: dir > 0 ? -0.65 : -0.35, right: dir > 0 ? -0.35 : -0.65 };
    if (mem.mt < 2.5) return { left: dir > 0 ? 0.35 : 0.65, right: dir > 0 ? 0.65 : 0.35 };
    mem.mode = 0;
    mem.pr = 0;
    mem.posh.length = 0;
  }

  return { left: cl(v - steer, -1, 1), right: cl(v + steer, -1, 1) };
}

