    mem.sw = 0;
    mem.posh.length = 0;
    mem.mode = 0;
  }
  mem.prevTX = tx;
  mem.prevTY = ty;

  var dhd = n180(hd - mem.ph);
  mem.ph = hd;
  mem.hrate = 0.8 * mem.hrate + 0.2 * (dhd / 0.05);

