    var v = (obs.rays && obs.rays[i] !== undefined) ? +obs.rays[i] : 10;
    if (!isFinite(v) || v <= 0) v = 10;
    v = cl(v, 0.05, 10);
    if (v < mem.rays[i]) {
      mem.rays[i] = 0.3 * mem.rays[i] + 0.7 * v;
    } else {
      mem.rays[i] = 0.8 * mem.rays[i] + 0.2 * v;
    }
