  var hPen = dist < 3 ? 0.12 : (dist < 8 ? 0.05 : 0.025);
  var bestA = cl(hErr, -60, 60);
  var bestS = -1e9;

  for (var a = -60; a <= 60; a += 5) {
    var c = clrAt(a);
    var ad = Math.abs(n180(a - hErr));
    var sc = Math.min(c, 8) - hPen * ad;
    if (c < 3.5) sc -= (3.5 - c) * 2.5;
    if (c < 1.5) sc -= (1.5 - c) * 5;
