  if (minR < 2.5) v = Math.min(v, cl(minR / 2.5, 0.1, 1));
  v *= 1 - 0.15 * Math.abs(bestA) / 60;
  if (dist < 2.5) v = Math.min(v, cl(dist / 2.5, 0.15, 1));
  v = cl(v, 0.12, 1);

  mem.posh.push([t, px, py]);
