    if (gd > 0.3 && spd > 0.2) {
      var gpsH = Math.atan2(gdy, gdx) * 180 / Math.PI;
      var be = n180(gpsH - hd);
      if (Math.abs(be) < 60) mem.bias = cl(mem.bias * 0.97 + be * 0.03, -25, 25);
