  let dangerC = 8;

  for (let i = 0; i < 5; i++) {
    const a = h + angOffs[i] * DEG;
    const rel = wrap(a - bestAng);
    const along = r[i] * Math.cos(rel);
    const lat = Math.abs(r[i] * Math.sin(rel));

    if (along > 0 && lat < 0.68) {
