  const downRate = escaping ? 0.55 : 0.34;

  let outL = slew(mem.cmdL, wantL, upRate, downRate);
  let outR = slew(mem.cmdR, wantR, upRate, downRate);

  if (Math.abs(wantL) < 0.015 && Math.abs(wantR) < 0.015) {
