  const TWO = 2 * PI;
  const DEG = PI / 180;
  const RES = 0.25;
  const W = 161;
  const N = W * W;
  const RAY_ANG = [-60 * DEG, -30 * DEG, 0, 30 * DEG, 60 * DEG];
  const HARD_R = 0.40;
  const MARGIN = 0.40;

  function clamp(v, lo, hi) {
    return v < lo ? lo : (v > hi ? hi : v);
  }

  function wrap(a) {
    a = a % TWO;
    if (a > PI) a -= TWO;
    if (a < -PI) a += TWO;
