  if (mem.lastAvg === undefined) mem.lastAvg = 0;
  if (mem.bias === undefined) mem.bias = 0;
  if (mem.baseSmooth === undefined) mem.baseSmooth = h;
  if (mem.escapeUntil === undefined) mem.escapeUntil = -1;
