    const sx = clamp(Math.round(sxw / RES), 0, W - 1);
    const sy = clamp(Math.round(syw / RES), 0, W - 1);
    const gx = clamp(Math.round(gxw / RES), 0, W - 1);
    const gy = clamp(Math.round(gyw / RES), 0, W - 1);

