    gscore.fill(1e9);
    const came = new Int32Array(N);
    came.fill(-1);
    const closed = new Uint8Array(N);

    const heapK = [];
    const heapF = [];

    function push(k, f) {
      let i = heapK.length;
      heapK.push(k);
      heapF.push(f);
      while (i > 0) {
