  let dangerFinal = 10;
  let dangerIdx = 2;

  for (let i = 0; i < 5; i++) {
    const rr = r[i];
    const obsAng = h + RAY_ANG[i];
    const rel = wrap(obsAng - desired);
    const along = rr * Math.cos(rel);
    const latAbs = Math.abs(rr * Math.sin(rel));

    if (along > 0) {
      if (latAbs < 0.62 && along < clearFinal) clearFinal = along;
      if (latAbs < 0.42 && along < dangerFinal) {
        dangerFinal = along;
        dangerIdx = i;
      }
    }
  }

  let escaping = t < mem.escapeUntil;

