    const dh = Math.abs(wrap(h - mem.checkH));
    const cmdAvg = Math.abs(mem.lastAvg);

    if (t > 1.1 && moved < 0.08 && Math.abs(spd) < 0.12 && cmdAvg > 0.14) {
