      const openR = r[1] + 0.7 * r[0];
      const side = openL >= openR ? 1 : -1;

      mem.escapeUntil = t + 0.52;
      mem.escapeAngle = side * 0.55;
      mem.stuckN = 0;
      mem.checkT = t;
      mem.checkX = x;
      mem.checkY = y;
      mem.checkH = h;
      escaping = true;
    }
  }

  const err = wrap(desired - h);
  const errAbs = Math.abs(err);

  let speedCmd = 0.82;

  if (errAbs < 0.13 && clearFinal > 2.8 && dangerFinal > 1.3 && minRay > 1.2) {
    speedCmd = 0.96;
  }

  if (errAbs > 0.14) {
    speedCmd *= clamp(1 - (errAbs - 0.14) / 1.05, 0.06, 1);
  }
  if (errAbs > 1.05) speedCmd = Math.min(speedCmd, 0.12);

  if (clearFinal < 2.40) {
    speedCmd *= clamp((clearFinal - 0.50) / 1.90, 0.04, 1);
  }

  if (dangerFinal < 0.95) {
    speedCmd = Math.min(speedCmd, Math.max(0, (dangerFinal - 0.46) * 0.55));
  }

  if (minRay < 0.64) speedCmd = Math.min(speedCmd, 0.10);
  if (edge < 0.90) speedCmd = Math.min(speedCmd, 0.18);

  if (dGoal < 2.10) {
    speedCmd = Math.min(speedCmd, Math.max(0.08, (dGoal - 0.35) * 0.50));
  }

  if (speedCmd < 0.035) {
    speedCmd = 0;
  } else if (speedCmd < 0.17) {
    if (errAbs < 0.45 && clearFinal > 0.95 && dangerFinal > 0.75) {
      speedCmd = 0.17;
    } else {
      speedCmd = 0;
    }
  }

  let maxDiff = 0.50;

  if (errAbs < 0.10) maxDiff = Math.min(maxDiff, 0.32);
  if (minRay < 1.20) maxDiff = Math.min(maxDiff, 0.42);
  if (minRay < 0.90) maxDiff = Math.min(maxDiff, 0.30);
  if (minRay < 0.60) maxDiff = Math.min(maxDiff, 0.20);
  if (clearFinal < 1.25) maxDiff = Math.min(maxDiff, 0.36);
  if (dangerFinal < 0.85) maxDiff = Math.min(maxDiff, 0.26);

  if (speedCmd > 0.55) maxDiff = Math.min(maxDiff, 0.38);
  if (speedCmd > 0.75) maxDiff = Math.min(maxDiff, 0.30);

  if (errAbs > 1.20 && minRay > 0.85 && clearFinal > 1.10) {
    maxDiff = Math.max(maxDiff, 0.52);
  }

  let omegaDes = clamp(1.25 * err, -0.90, 0.90);
  if (errAbs > 1.00) omegaDes = clamp(1.80 * err, -1.35, 1.35);

  let diff = 0.45 * omegaDes + 0.30 * (omegaDes - mem.yawRate);

  if (diff > 0 && leftClear < 0.82) {
    diff *= clamp((leftClear - 0.26) / 0.56, 0.03, 1);
  }
  if (diff < 0 && rightClear < 0.82) {
    diff *= clamp((rightClear - 0.26) / 0.56, 0.03, 1);
