  const x = isFinite(Number(obs.x)) ? Number(obs.x) : 0;
  const y = isFinite(Number(obs.y)) ? Number(obs.y) : 0;
  let hdg = Number(obs.heading);
  if (!isFinite(hdg)) hdg = 0;
  const h = wrap(hdg * DEG);

  let tgtX = Number(obs.targetX);
  let tgtY = Number(obs.targetY);
  if (!isFinite(tgtX)) tgtX = x;
  if (!isFinite(tgtY)) tgtY = y;
  let tIdx = Number(obs.targetIndex);
  if (!isFinite(tIdx)) tIdx = 0;

  let spd = Number(obs.speed);
  if (!isFinite(spd)) spd = 0;

  const raysIn = (obs.rays && obs.rays.length >= 5)
    ? obs.rays
    : [10, 10, 10, 10, 10];

  const raw = [10, 10, 10, 10, 10];
  const r = [10, 10, 10, 10, 10];
  for (let i = 0; i < 5; i++) {
    let v = Number(raysIn[i]);
    if (!isFinite(v)) v = 10;
    if (v < 0.02) v = 0.02;
    if (v > 10) v = 10;
    raw[i] = v;
    r[i] = Math.max(0.03, v - 0.05);
  }

