    mem.occ = new Uint8Array(N);
    mem.hard = new Uint8Array(N);
    mem.free = new Uint8Array(N);
    mem.path = [];
    mem.lastPlan = -1e9;
    mem.lastTX = 1e9;
    mem.lastTY = 1e9;
    mem.lastIdx = -1;
    mem.prevT = t;
    mem.prevH = h;
    mem.yawRate = 0;
    mem.cmdL = 0;
    mem.cmdR = 0;
    mem.bias = 0;
    mem.baseSmooth = h;
    mem.escapeUntil = -1;
    mem.escapeAngle = 0;
    mem.stuckN = 0;
    mem.checkT = t;
    mem.checkX = x;
    mem.checkY = y;
    mem.checkH = h;
