      const ey = y + sa * rr;
      const cix = Math.round(ex / RES);
      const ciy = Math.round(ey / RES);

      if (cix >= 0 && cix < W && ciy >= 0 && ciy < W) {
        mem.occ[ciy * W + cix] = 1;
      }

      const radCells = Math.ceil(HARD_R / RES);
      for (let dy = -radCells; dy <= radCells; dy++) {
        for (let dx = -radCells; dx <= radCells; dx++) {
          const gx = cix + dx;
          const gy = ciy + dy;
          if (gx < 0 || gx >= W || gy < 0 || gy >= W) continue;
          const wx = gx * RES - ex;
          const wy = gy * RES - ey;
          if (wx * wx + wy * wy <= HARD_R * HARD_R) {
