  function planPath(sxw, syw, gxw, gyw, relaxed) {
    const sx = clamp(Math.round(sxw / RES), 0, W - 1);
    const sy = clamp(Math.round(syw / RES), 0, W - 1);
    const gx = clamp(Math.round(gxw / RES), 0, W - 1);
    const gy = clamp(Math.round(gyw / RES), 0, W - 1);

    const sk = sy * W + sx;
    const gk = gy * W + gx;

    if (sk === gk) return [{ x: gxw, y: gyw }];

    function heur(ix, iy) {
      const dx = Math.abs(ix - gx);
      const dy = Math.abs(iy - gy);
      return Math.max(dx, dy) + (Math.SQRT2 - 1) * Math.min(dx, dy);
