    if (40 - x < 1.2) px -= (1.2 - (40 - x)) / 1.2;
    if (y < 1.2) py += (1.2 - y) / 1.2;
    if (40 - y < 1.2) py -= (1.2 - (40 - y)) / 1.2;

    vx += 2.0 * px;
    vy += 2.0 * py;

