      gamma = RAY_ANG[minIdx];
    } else if (dangerFinal < 0.56 && (spd > 0.04 || Math.abs(mem.lastAvg) > 0.10)) {
      trig = true;
      gamma = RAY_ANG[dangerIdx];
    } else if (clearFinal < 0.68 && Math.abs(spd) > 0.08) {
      trig = true;
      gamma = RAY_ANG[dangerIdx];
    }

    if (trig) {
      mem.escapeUntil = t + 0.42;
      mem.escapeAngle = gamma;
      mem.stuckN = 0;
      mem.checkT = t;
      mem.checkX = x;
      mem.checkY = y;
      mem.checkH = h;
      escaping = true;
