  if (edge < 0.85) speedCmd = Math.min(speedCmd, 0.20);
  if (dGoal < 1.15) speedCmd = Math.min(speedCmd, 0.42);

  if (speedCmd < 0.035) {
    speedCmd = 0;
  } else if (speedCmd < 0.17) {
    if (errAbs < 0.45 && clearFinal > 0.95 && dangerFinal > 0.75) {
      speedCmd = 0.17;
    } else {
      speedCmd = 0;
    }
  }

  let maxDiff = 0.62;

  if (minRay < 1.2) maxDiff = Math.min(maxDiff, 0.46);
  if (minRay < 0.90) maxDiff = Math.min(maxDiff, 0.32);
  if (minRay < 0.60) maxDiff = Math.min(maxDiff, 0.20);
  if (clearFinal < 1.25) maxDiff = Math.min(maxDiff, 0.38);
  if (dangerFinal < 0.85) maxDiff = Math.min(maxDiff, 0.28);
  if (errAbs > 1.2 && minRay > 0.90 && clearFinal > 1.2) {
