    mem.lastTX = 1e9;
    mem.lastTY = 1e9;
    mem.lastIdx = -1;
    mem.prevT = t;
    mem.prevH = h;
    mem.yawRate = 0;
    mem.cmdL = 0;
    mem.cmdR = 0;
    mem.bias = 0;
    mem.baseSmooth = h;
    mem.escapeUntil = -1;
    mem.escapeAngle = 0;
    mem.escapeStraight = false;
    mem.stuckN = 0;
    mem.checkT = t;
    mem.checkX = x;
