    const gk = gy * W + gx;

    if (sk === gk) return [{ x: gxw, y: gyw }];

    function heur(ix, iy) {
      const dx = Math.abs(ix - gx);
      const dy = Math.abs(iy - gy);
      return Math.max(dx, dy) + (Math.SQRT2 - 1) * Math.min(dx, dy);
