    gscore.fill(1e9);
    const came = new Int32Array(N);
    came.fill(-1);
    const closed = new Uint8Array(N);

    const heapK = [];
    const heapF = [];

    function push(k, f) {
      let i = heapK.length;
      heapK.push(k);
      heapF.push(f);
      while (i > 0) {
        const p = (i - 1) >> 1;
        if (heapF[p] <= heapF[i]) break;
        const tk = heapK[p];
        heapK[p] = heapK[i];
        heapK[i] = tk;
        const tf = heapF[p];
        heapF[p] = heapF[i];
        heapF[i] = tf;
