      straight = dangerFinal < 0.45;
      gamma = straight ? 0 : RAY_ANG[dangerIdx];
    } else if (clearFinal < 0.68 && Math.abs(spd) > 0.08) {
      trig = true;
      gamma = RAY_ANG[dangerIdx];
      straight = false;
    }

    if (trig) {
      mem.escapeUntil = t + (straight ? 0.46 : 0.42);
