      mem.stuckN++;
    } else {
      mem.stuckN = Math.max(0, mem.stuckN - 1);
    }

    mem.checkT = t;
    mem.checkX = x;
    mem.checkY = y;
    mem.checkH = h;

    const severeStuck =
      mem.stuckN >= 2 ||
      (mem.stuckN >= 1 && minRay < 0.85 && Math.abs(spd) < 0.08);

    if (severeStuck && t > mem.escapeUntil) {
      mem.escapeUntil = t + (mem.stuckN >= 2 ? 0.72 : 0.55);
      mem.escapeAngle = 0;
      mem.escapeStraight = true;
      mem.stuckN = 0;
      mem.checkT = t;
      mem.checkX = x;
      mem.checkY = y;
      mem.checkH = h;
      escaping = true;
    }
  }

  const err = wrap(desired - h);
  const errAbs = Math.abs(err);

  const eC = clamp(err, -1.45, 1.45);
  const yawCmd = 1.75 * eC - 0.42 * mem.yawRate;
  let diff = yawCmd / 1.20;

  let speedCmd = 0.64;

  if (errAbs < 0.18 && clearFinal > 2.6 && minRay > 1.2) speedCmd = 0.80;

  if (errAbs < 0.10 && clearFinal > 3.8 && minRay > 2.8 && Math.abs(mem.yawRate) < 0.45) {
    speedCmd = 0.86;
  }

  if (errAbs > 0.20) {
    speedCmd *= clamp(1 - (errAbs - 0.20) / 1.35, 0.07, 1);
  }
  if (errAbs > 1.05) speedCmd = Math.min(speedCmd, 0.10);

  if (clearFinal < 2.25) {
    speedCmd *= clamp((clearFinal - 0.55) / 1.70, 0.04, 1);
  }

  if (dangerFinal < 0.95) {
    speedCmd = Math.min(speedCmd, Math.max(0, (dangerFinal - 0.48) * 0.55));
  }

  if (minRay < 0.65) speedCmd = Math.min(speedCmd, 0.12);
  if (edge < 0.85) speedCmd = Math.min(speedCmd, 0.20);
  if (dGoal < 1.15) speedCmd = Math.min(speedCmd, 0.42);

  if (speedCmd < 0.035) {
    speedCmd = 0;
  } else if (speedCmd < 0.17) {
    if (errAbs < 0.45 && clearFinal > 0.95 && dangerFinal > 0.75) {
      speedCmd = 0.17;
    } else {
      speedCmd = 0;
    }
  }

  let maxDiff = 0.62;

  if (minRay < 1.2) maxDiff = Math.min(maxDiff, 0.46);
  if (minRay < 0.90) maxDiff = Math.min(maxDiff, 0.32);
  if (minRay < 0.60) maxDiff = Math.min(maxDiff, 0.20);
  if (clearFinal < 1.25) maxDiff = Math.min(maxDiff, 0.38);
  if (dangerFinal < 0.85) maxDiff = Math.min(maxDiff, 0.28);
  if (errAbs > 1.2 && minRay > 0.90 && clearFinal > 1.2) {
    maxDiff = Math.max(maxDiff, 0.55);
  }

  if (speedCmd > 0.20) {
    maxDiff = Math.min(maxDiff, 2 * (0.95 - speedCmd));
  }
  if (speedCmd === 0 && errAbs < 0.08) {
    maxDiff = Math.min(maxDiff, 0.18);
  }

  if (diff > 0 && leftClear < 0.85) {
    diff *= clamp((leftClear - 0.30) / 0.55, 0.03, 1);
  }
  if (diff < 0 && rightClear < 0.85) {
    diff *= clamp((rightClear - 0.30) / 0.55, 0.03, 1);
  }

  maxDiff = Math.max(0.05, maxDiff);
  diff = clamp(diff, -maxDiff, maxDiff);

  let wantL = 0;
  let wantR = 0;

  if (escaping) {
    const gamma = mem.escapeAngle || 0;
    const align = mem.escapeStraight
      ? 0
      : clamp(1.05 * Math.sin(gamma), -0.38, 0.38);
    const back = mem.escapeStraight ? 0.22 : 0.19;
    wantL = -back - align / 2;
    wantR = -back + align / 2;
  } else {
    const avg = speedCmd;
    wantL = avg - diff / 2;
    wantR = avg + diff / 2;
  }

  function slew(cur, target, up, down) {
    const d = target - cur;
    if (d > up) return cur + up;
    if (d < -down) return cur - down;
    return target;
  }

  const upRate = escaping ? 0.34 : 0.18;
  const downRate = escaping ? 0.55 : 0.34;

  let outL = slew(mem.cmdL, wantL, upRate, downRate);
  let outR = slew(mem.cmdR, wantR, upRate, downRate);

  if (Math.abs(wantL) < 0.015 && Math.abs(wantR) < 0.015) {
    outL = 0;
    outR = 0;
  }

  outL = clamp(outL, -0.95, 0.95);
  outR = clamp(outR, -0.95, 0.95);

  function deadzone(u) {
    if (Math.abs(u) < 0.02) return 0;
    if (u > 0) return u < 0.13 ? 0.13 : clamp(u, 0, 0.95);
    return u > -0.13 ? -0.13 : clamp(u, -0.95, 0);
  }

  const finalL = deadzone(outL);
  const finalR = deadzone(outR);

  mem.cmdL = finalL;
  mem.cmdR = finalR;
  mem.lastAvg = (finalL + finalR) * 0.5;

  return { left: finalL, right: finalR };
}

function act(obs, mem) {
  const PI = Math.PI;
  const TWO = 2 * PI;
  const DEG = PI / 180;
  const RES = 0.25;
  const W = 161;
  const N = W * W;
  const RAY_ANG = [-60 * DEG, -30 * DEG, 0, 30 * DEG, 60 * DEG];
  const HARD_R = 0.43;
  const MARGIN = 0.42;

  function clamp(v, lo, hi) {
    return v < lo ? lo : (v > hi ? hi : v);
  }

  function wrap(a) {
    a = a % TWO;
    if (a > PI) a -= TWO;
    if (a < -PI) a += TWO;
    return a;
  }

  if (!mem) mem = {};

  const t = isFinite(Number(obs.t)) ? Number(obs.t) : 0;
  const x = isFinite(Number(obs.x)) ? Number(obs.x) : 0;
  const y = isFinite(Number(obs.y)) ? Number(obs.y) : 0;
  let hdg = Number(obs.heading);
  if (!isFinite(hdg)) hdg = 0;
  const h = wrap(hdg * DEG);

  let tgtX = Number(obs.targetX);
  let tgtY = Number(obs.targetY);
  if (!isFinite(tgtX)) tgtX = x;
  if (!isFinite(tgtY)) tgtY = y;
  let tIdx = Number(obs.targetIndex);
  if (!isFinite(tIdx)) tIdx = 0;

  if (mem && mem.init && mem.occ && mem.hard && mem.free) {
    const oldT = isFinite(Number(mem.prevT)) ? Number(mem.prevT) : 0;
    const oldIdx = isFinite(Number(mem.lastIdx)) ? Number(mem.lastIdx) : -1;
    if (t + 0.25 < oldT || tIdx < oldIdx) {
      mem.init = false;
      mem.occ = null;
      mem.hard = null;
      mem.free = null;
      mem.path = [];
    }
  }

  let spd = Number(obs.speed);
  if (!isFinite(spd)) spd = 0;

  const raysIn = (obs.rays && obs.rays.length >= 5)
    ? obs.rays
    : [10, 10, 10, 10, 10];

  const raw = [10, 10, 10, 10, 10];
  const r = [10, 10, 10, 10, 10];
  for (let i = 0; i < 5; i++) {
    let v = Number(raysIn[i]);
    if (!isFinite(v)) v = 10;
    if (v < 0.02) v = 0.02;
    if (v > 10) v = 10;
    raw[i] = v;
    r[i] = Math.max(0.03, v - 0.05);
  }

  if (!mem.init || !mem.occ || !mem.hard || !mem.free || mem.occ.length !== N) {
    mem.init = true;
    mem.occ = new Uint8Array(N);
    mem.hard = new Uint8Array(N);
    mem.free = new Uint8Array(N);
    mem.path = [];
    mem.lastPlan = -1e9;
    mem.lastTX = 1e9;
    mem.lastTY = 1e9;
    mem.lastIdx = -1;
    mem.prevT = t;
    mem.prevH = h;
    mem.yawRate = 0;
    mem.cmdL = 0;
    mem.cmdR = 0;
    mem.bias = 0;
    mem.baseSmooth = h;
    mem.escapeUntil = -1;
    mem.escapeAngle = 0;
    mem.escapeStraight = false;
    mem.stuckN = 0;
    mem.checkT = t;
    mem.checkX = x;
    mem.checkY = y;
    mem.checkH = h;
    mem.lastAvg = 0;
