  mem.prevH = h;

  const targetChanged =
    Math.abs(tgtX - mem.lastTX) > 0.035 ||
    Math.abs(tgtY - mem.lastTY) > 0.035 ||
    tIdx !== mem.lastIdx;

  if (targetChanged) {
    mem.path = [];
    mem.lastPlan = -1e9;
    mem.bias = 0;
    mem.baseSmooth = h;
    mem.escapeUntil = -1;
    mem.escapeStraight = false;
    mem.stuckN = 0;
    mem.checkT = t;
    mem.checkX = x;
    mem.checkY = y;
    mem.checkH = h;
