  mem.lastTX = tgtX;
  mem.lastTY = tgtY;
  mem.lastIdx = tIdx;

  for (let i = 0; i < 5; i++) {
    const ang = h + RAY_ANG[i];
    const ca = Math.cos(ang);
    const sa = Math.sin(ang);
    const rr = raw[i];
    const hit = rr < 9.6;

    const dmax = hit
      ? Math.max(0, rr - 0.18)
      : Math.min(rr, 5.0);

    for (let d = 0.08; d < dmax; d += RES * 0.7) {
      const ix = Math.round((x + ca * d) / RES);
      const iy = Math.round((y + sa * d) / RES);
      if (ix >= 0 && ix < W && iy >= 0 && iy < W) {
        const k = iy * W + ix;
        if (!mem.occ[k] && !mem.hard[k]) mem.free[k] = 1;
      }
    }

    if (hit) {
      const ex = x + ca * rr;
      const ey = y + sa * rr;
      const cix = Math.round(ex / RES);
      const ciy = Math.round(ey / RES);

      if (cix >= 0 && cix < W && ciy >= 0 && ciy < W) {
        mem.occ[ciy * W + cix] = 1;
      }

      const radCells = Math.ceil(HARD_R / RES);
      for (let dy = -radCells; dy <= radCells; dy++) {
        for (let dx = -radCells; dx <= radCells; dx++) {
          const gx = cix + dx;
          const gy = ciy + dy;
          if (gx < 0 || gx >= W || gy < 0 || gy >= W) continue;
          const wx = gx * RES - ex;
          const wy = gy * RES - ey;
          if (wx * wx + wy * wy <= HARD_R * HARD_R) {
            mem.hard[gy * W + gx] = 1;
          }
        }
      }
    }
  }

  function planPath(sxw, syw, gxw, gyw, relaxed) {
    const sx = clamp(Math.round(sxw / RES), 0, W - 1);
    const sy = clamp(Math.round(syw / RES), 0, W - 1);
    const gx = clamp(Math.round(gxw / RES), 0, W - 1);
    const gy = clamp(Math.round(gyw / RES), 0, W - 1);

    const sk = sy * W + sx;
    const gk = gy * W + gx;

    if (sk === gk) return [{ x: gxw, y: gyw }];

    function heur(ix, iy) {
      const dx = Math.abs(ix - gx);
      const dy = Math.abs(iy - gy);
      return Math.max(dx, dy) + (Math.SQRT2 - 1) * Math.min(dx, dy);
    }

    const gscore = new Float32Array(N);
    gscore.fill(1e9);
    const came = new Int32Array(N);
    came.fill(-1);
    const closed = new Uint8Array(N);

    const heapK = [];
    const heapF = [];

    function push(k, f) {
      let i = heapK.length;
      heapK.push(k);
      heapF.push(f);
      while (i > 0) {
        const p = (i - 1) >> 1;
        if (heapF[p] <= heapF[i]) break;
        const tk = heapK[p];
        heapK[p] = heapK[i];
        heapK[i] = tk;
        const tf = heapF[p];
        heapF[p] = heapF[i];
        heapF[i] = tf;
        i = p;
      }
    }

    function pop() {
      const top = heapK[0];
      const lastK = heapK.pop();
      const lastF = heapF.pop();
      if (heapK.length > 0) {
        heapK[0] = lastK;
        heapF[0] = lastF;
        let i = 0;
        while (true) {
          const l = i * 2 + 1;
          if (l >= heapK.length) break;
          const rr = l + 1;
          let s = i;
          if (heapF[l] < heapF[s]) s = l;
          if (rr < heapK.length && heapF[rr] < heapF[s]) s = rr;
          if (s === i) break;
          const tk = heapK[s];
          heapK[s] = heapK[i];
          heapK[i] = tk;
          const tf = heapF[s];
          heapF[s] = heapF[i];
          heapF[i] = tf;
          i = s;
        }
      }
      return top;
    }

    gscore[sk] = 0;
    push(sk, heur(sx, sy));

    let iter = 0;
    while (heapK.length > 0 && iter++ < 9000) {
      const k = pop();
      if (closed[k]) continue;
      closed[k] = 1;
      if (k === gk) break;

      const ix = k % W;
      const iy = (k / W) | 0;

      for (let oy = -1; oy <= 1; oy++) {
        for (let ox = -1; ox <= 1; ox++) {
