          const diag = ox !== 0 && oy !== 0;
          const step = diag ? Math.SQRT2 : 1.0;
          let cost = step;

          if (!isGoal) {
            if (relaxed) {
              if (ob) cost += 250;
              if (hb) cost += 8;
            }
            if (!mem.free[nk]) cost += 0.12;
          }

          if (diag) {
            const k1 = iy * W + nx;
            const k2 = ny * W + ix;
            if (!relaxed && !isGoal) {
              if ((mem.hard[k1] || mem.occ[k1]) ||
                  (mem.hard[k2] || mem.occ[k2])) continue;
            } else {
              if (mem.hard[k1] || mem.occ[k1]) cost += 2.2;
              if (mem.hard[k2] || mem.occ[k2]) cost += 2.2;
            }
          }

          const ng = gscore[k] + cost;
          if (ng < gscore[nk]) {
            gscore[nk] = ng;
            came[nk] = k;
            push(nk, ng + 1.18 * heur(nx, ny));
