        }
      }
    }

    if (gscore[gk] >= 1e8) return null;

    const arr = [];
    let cur = gk;
    let guard = 0;

    while (cur !== sk && cur !== -1 && guard++ < 6000) {
      arr.push({
        x: (cur % W) * RES,
        y: ((cur / W) | 0) * RES
      });
      cur = came[cur];
    }

    if (cur !== sk) return null;

    arr.reverse();
    arr.push({ x: gxw, y: gyw });
    return arr;
