  const frontNow = Math.min(r[2], r[1] + 0.16, r[3] + 0.16);
  const planInterval = (frontNow < 1.5 || Math.min(r[0], r[1], r[2], r[3], r[4]) < 0.9)
    ? 0.32
    : 0.48;

  const needPlan =
    targetChanged ||
    !mem.path ||
    mem.path.length === 0 ||
    (t - mem.lastPlan > planInterval);

  if (needPlan) {
    let p = planPath(x, y, tgtX, tgtY, false);
    if (!p) p = planPath(x, y, tgtX, tgtY, true);
    if (p && p.length) {
      mem.path = p;
    } else if (!mem.path || mem.path.length === 0) {
      mem.path = [{ x: tgtX, y: tgtY }];
    }
    mem.lastPlan = t;
  }

  const path = mem.path;
  const dGoal = Math.hypot(tgtX - x, tgtY - y);

  let bestI = 0;
  let bestD = 1e18;
  for (let i = 0; i < path.length; i++) {
    const dx = path[i].x - x;
    const dy = path[i].y - y;
    const dd = dx * dx + dy * dy;
    if (dd < bestD) {
      bestD = dd;
      bestI = i;
    }
