      } else {
        biasRaw -= (lat > 0 ? 1 : -1) * strength * 1.20;
      }
    }

    if (rr < 0.85) {
      const relH = RAY_ANG[i];
      const side = Math.sin(relH);
      if (Math.abs(side) > 0.10) {
        const strength = (0.85 - rr) / 0.85;
        biasRaw -= (side > 0 ? 1 : -1) * strength * 0.80;
      }
    }
  }

  biasRaw = clamp(biasRaw, -1.2, 1.2);
  const maxBiasStep = minRay < 0.8 ? 0.20 : 0.10;
  mem.bias = clamp(
    mem.bias + clamp(biasRaw - mem.bias, -maxBiasStep, maxBiasStep),
    -1.0,
    1.0
  );

  let desired = wrap(baseS + mem.bias);

  const edge = Math.min(x, 40 - x, y, 40 - y);
  if (edge < 1.2) {
    let vx = Math.cos(desired);
    let vy = Math.sin(desired);
    let px = 0;
    let py = 0;

    if (x < 1.2) px += (1.2 - x) / 1.2;
    if (40 - x < 1.2) px -= (1.2 - (40 - x)) / 1.2;
    if (y < 1.2) py += (1.2 - y) / 1.2;
    if (40 - y < 1.2) py -= (1.2 - (40 - y)) / 1.2;

    vx += 2.0 * px;
    vy += 2.0 * py;

    if (vx * vx + vy * vy > 1e-8) desired = Math.atan2(vy, vx);
  }

  let clearFinal = 10;
  let dangerFinal = 10;
  let dangerIdx = 2;

  for (let i = 0; i < 5; i++) {
    const rr = r[i];
    const obsAng = h + RAY_ANG[i];
    const rel = wrap(obsAng - desired);
    const along = rr * Math.cos(rel);
    const latAbs = Math.abs(rr * Math.sin(rel));

    if (along > 0) {
      if (latAbs < 0.62 && along < clearFinal) clearFinal = along;
      if (latAbs < 0.40 && along < dangerFinal) {
        dangerFinal = along;
        dangerIdx = i;
      }
    }
  }

  let escaping = t < mem.escapeUntil;

  if (!escaping && t > 0.4) {
    let trig = false;
    let gamma = 0;
    let straight = false;

    if (minRay < 0.50) {
      trig = true;
      gamma = 0;
      straight = true;
    } else if (dangerFinal < 0.56 && (spd > 0.04 || Math.abs(mem.lastAvg) > 0.10)) {
      trig = true;
      straight = dangerFinal < 0.45;
      gamma = straight ? 0 : RAY_ANG[dangerIdx];
    } else if (clearFinal < 0.68 && Math.abs(spd) > 0.08) {
      trig = true;
      gamma = RAY_ANG[dangerIdx];
      straight = false;
    }

    if (trig) {
      mem.escapeUntil = t + (straight ? 0.46 : 0.42);
      mem.escapeAngle = gamma;
      mem.escapeStraight = straight;
      mem.stuckN = 0;
      mem.checkT = t;
      mem.checkX = x;
      mem.checkY = y;
      mem.checkH = h;
      escaping = true;
    }
  }

  if (!escaping && t - mem.checkT > 0.8) {
    const moved = Math.hypot(x - mem.checkX, y - mem.checkY);
    const cmdAvg = Math.abs(mem.lastAvg);

    if (t > 1.1 && moved < 0.08 && Math.abs(spd) < 0.12 && cmdAvg > 0.14) {
      mem.stuckN++;
    } else {
      mem.stuckN = Math.max(0, mem.stuckN - 1);
    }

    mem.checkT = t;
    mem.checkX = x;
    mem.checkY = y;
    mem.checkH = h;

    const severeStuck =
      mem.stuckN >= 2 ||
