const KP = 0.010;       // differential per degree of heading error
const KD = 0.0025;      // differential damping per deg/s of heading rate
const WMAX = 0.5;       // max differential
const WMIN = 0.12;      // minimum differential once outside deadband (motors ignore small turns)
const DEAD = 4;         // heading deadband (deg)
const CAP = 3.0;        // clearance beyond this counts as equally good
const BLOCK = 1.8;      // clearance below this = blocked
const GOAL_OPEN = 2.2;  // goal cone must be this clear to steer straight at goal
const HOLD_T = 2.0;     // s to hold an avoidance heading before re-picking
const STUCK_T = 3.0;    // s without moving/turning before escape
const STUCK_D = 0.25;   // m
const BACK_T = 1.2;     // reverse escape duration (s)

// Motor deadband compensation
function dz(u) {
  if (Math.abs(u) < 0.03) return 0;
  return Math.sign(u) * Math.max(Math.abs(u), 0.10);
}

// Clearance in direction a (deg, relative to heading); rays at -60,-30,0,30,60
function clearAt(r, a) {
  if (a <= -60) return r[0] * 0.8;
  if (a >= 60) return r[4] * 0.8;
  const p = (a + 60) / 30;
  const i = Math.min(3, Math.floor(p));
  const f = p - i;
  return r[i] * (1 - f) + r[i + 1] * f;
}

function act(obs, mem) {
  // ---- target (flag when checkpoints exhausted) ----
  const tx = isFinite(obs.targetX) ? obs.targetX : obs.goalX;
  const ty = isFinite(obs.targetY) ? obs.targetY : obs.goalY;
  const hRaw = isFinite(obs.heading) ? obs.heading : 0;

  // ---- sanitize rays, 3-tick minimum filter against dropouts ----
  const raw = Array.isArray(obs.rays) ? obs.rays : [];
  const cur = [0, 1, 2, 3, 4].map(i => {
    const v = raw[i];
    return (typeof v === 'number' && isFinite(v)) ? clamp(v, 0, 10) : 10;
  });
  mem.rh = mem.rh || [];
  mem.rh.push(cur);
  if (mem.rh.length > 3) mem.rh.shift();
  const r = [0, 1, 2, 3, 4].map(i => Math.min(...mem.rh.map(a => a[i])));

  // ---- time ----
  const t = (typeof obs.t === 'number' && isFinite(obs.t)) ? obs.t : (mem.t || 0) + 0.05;

  if (!mem.init) {
    mem.init = true;
    mem.lastIdx = obs.targetIndex;
    mem.anchor = { x: obs.x, y: obs.y, h: hRaw, t: t };
    mem.escT = 0;
    mem.escSide = 1;
    mem.tp = t - 0.05;
    mem.prevH = hRaw;
    mem.rate = 0;
    mem.target = null;
    mem.tSel = -1e9;
    mem.lastL = 0;
    mem.lastR = 0;
    mem.hb = 0;          // estimated compass offset (deg)
    mem.hist = [];
  }
  const dt = clamp(t - mem.tp, 0.01, 0.5);
  mem.tp = t;
  mem.t = t;

  // ---- compass offset estimate from GPS course on straight runs ----
  if (mem.hist.length === 0 || t - mem.hist[mem.hist.length - 1].t >= 0.5) {
    mem.hist.push({ x: obs.x, y: obs.y, h: hRaw, t: t });
    if (mem.hist.length > 5) mem.hist.shift();
    if (mem.hist.length === 5) {
      const a = mem.hist[0], b = mem.hist[4];
      const d = Math.hypot(b.x - a.x, b.y - a.y);
      const turn = Math.abs(wrap(b.h - a.h));
      if (b.t - a.t >= 1.5 && d > 1.0 && turn < 10 &&
          (mem.lastL + mem.lastR) > 0.5 && Math.abs(mem.lastL - mem.lastR) < 0.12) {
        const course = Math.atan2(b.y - a.y, b.x - a.x) * 180 / Math.PI;
        const e = wrap(b.h - course);
        mem.hb = clamp(mem.hb + 0.15 * wrap(e - mem.hb), -25, 25);
      }
    }
  }
  const h = wrap(hRaw - mem.hb);

  // ---- new checkpoint: reset memories ----
  if (obs.targetIndex !== mem.lastIdx) {
    mem.lastIdx = obs.targetIndex;
    mem.anchor = { x: obs.x, y: obs.y, h: h, t: t };
    mem.target = null;
    mem.escT = 0;
  }

  // ---- goal geometry ----
  const dx = tx - obs.x, dy = ty - obs.y;
  const dist = Math.hypot(dx, dy);
  const err = wrap(Math.atan2(dy, dx) * 180 / Math.PI - h);

  // ---- smoothed heading rate (deg/s) ----
  const rawRate = wrap(h - mem.prevH) / dt;
  mem.rate = 0.6 * mem.rate + 0.4 * rawRate;
  mem.prevH = h;

  const reverse = (side) => {
    const l = dz(-0.3 - 0.2 * side), rr = dz(-0.3 + 0.2 * side);
    mem.lastL = l; mem.lastR = rr;
    return { left: l, right: rr };
  };

  // ---- ongoing escape ----
  if (mem.escT > 0) {
    mem.escT -= dt;
    return reverse(mem.escSide);
  }

  // ---- stuck detection (moving or turning counts as progress) ----
  const moved = Math.hypot(obs.x - mem.anchor.x, obs.y - mem.anchor.y);
  const turned = Math.abs(wrap(h - mem.anchor.h));
  const commanding = Math.abs(mem.lastL) + Math.abs(mem.lastR) > 0.15;
  if (moved > STUCK_D || turned > 20) {
    mem.anchor = { x: obs.x, y: obs.y, h: h, t: t };
  } else if (t - mem.anchor.t > STUCK_T && dist > 1.0 && commanding) {
    mem.escSide = (clearAt(r, 45) >= clearAt(r, -45)) ? 1 : -1;
    mem.escT = BACK_T;
    mem.anchor = { x: obs.x, y: obs.y, h: h, t: t };
    mem.target = null;
    return reverse(mem.escSide);
  }

  // ---- choose steering direction (relative angle aRel) ----
  let aRel;
  const gOpen = Math.min(clearAt(r, err - 15), clearAt(r, err), clearAt(r, err + 15));
  if (Math.abs(err) <= 70 && gOpen >= GOAL_OPEN) {
    mem.target = null;
    aRel = err;
  } else {
    const prev = (mem.target === null) ? null : wrap(mem.target - h);
    const needSel = prev === null || (t - mem.tSel > HOLD_T) ||
                    clearAt(r, prev) < BLOCK || Math.abs(prev) > 80;
    if (needSel) {
      let best = 0, bestS = -1e9;
      for (let a = -90; a <= 90; a += 10) {
        const c = clearAt(r, a);
        let s = Math.min(c, CAP);
        if (c < BLOCK) s -= 4 + 3 * (BLOCK - c);          // blocked: strongly avoid
        s -= Math.abs(a - err) / 40;                       // goal pull
        if (prev !== null) s -= Math.abs(a - prev) / 60;   // hysteresis
        if (s > bestS) { bestS = s; best = a; }
      }
      mem.target = h + best;
      mem.tSel = t;
    }
    aRel = wrap(mem.target - h);
  }

  // ---- boxed in: nothing clear toward the chosen heading and front tight -> back out ----
  if (clearAt(r, aRel) < 0.8 && r[2] < 1.0 && mem.escT <= 0) {
    mem.escSide = (clearAt(r, 45) >= clearAt(r, -45)) ? 1 : -1;
    mem.escT = BACK_T;
    mem.anchor = { x: obs.x, y: obs.y, h: h, t: t };
    mem.target = null;
    return reverse(mem.escSide);
  }

  // ---- steering: P on relative angle with rate damping, pivot-strength minimum ----
  let u = 0;
  if (Math.abs(aRel) > DEAD) {
    u = KP * aRel - KD * mem.rate;
    if (Math.abs(u) < WMIN) u = Math.sign(u) * WMIN;
    u = clamp(u, -WMAX, WMAX);
  }

  // ---- speed: slow when target direction, front, or sides are tight; pivot when far off ----
  const cB = clearAt(r, aRel);
  let v = VMAX * clamp((cB - 1.0) / 1.5, 0, 1) * clamp(1 - Math.abs(aRel) / 50, 0, 1);
  v *= clamp((r[2] - 0.9) / 1.2, 0, 1);
  v *= clamp((Math.min(r[1], r[3]) - 0.6) / 1.0, 0.3, 1);
  if (dist < 1.2) v *= 0.6;

  const L = dz(clamp(v - u, -1, 1));
  const R = dz(clamp(v + u, -1, 1));
  mem.lastL = L;
  mem.lastR = R;
  return { left: L, right: R };
}
